window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7079db790b9b056c"]={"versions": [{"id": "FIG-7079db790b9b056c", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses der Schutzfunktion <code>E2E_P04Protect</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 4). Das Diagramm spezifiziert die Gesamtabfolge der Schutzschritte bei der Absicherung eines zu übertragenden Datenbereichs auf Senderseite.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitätsaufruf / Funktion</strong>: <code>E2E_P04Protect(Config, State, Data, Length)</code></li>\n<li><strong>Eingangsparameter</strong>:</li>\n<li><code>Config</code>: Konfigurationsstruktur des Profils 4</li>\n<li><code>State</code>: Zustandsstruktur des Schutzes</li>\n<li><code>Data</code>: Zeiger auf das zu schützende Daten-Array</li>\n<li><code>Length</code>: Länge der Daten in Bytes</li>\n<li><strong>Aktionen / Sub-Aktivitäten</strong> (jeweils mit Unterdiagramm-Symbol gekennzeichnet):</li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Write Length</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Write DataID</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n<li><strong>Knoten</strong>: Ein Startknoten (Initial Node) und drei Endknoten (Activity Final Nodes) für Rückgabewerte:</li>\n<li><code>INPUTERR_NULL</code> (vollständig: <code>E2E_E_INPUTERR_NULL</code>)</li>\n<li><code>return E2E_E_OK</code></li>\n<li><code>return E2E_...</code> (vollständig: <code>return E2E_E_INPUTERR_WRONG</code>)</li>\n<li><strong>Guards</strong>: <code>[input ok]</code>, <code>[wrong input]</code>, impliziter Null-Fehler-Pfad.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf beginnt am Startknoten beim Aufruf von <code>E2E_P04Protect(Config, State, Data, Length)</code>.</li>\n<li>Erste Aktion ist <code>Verify inputs of the protect function</code>.</li>\n<li>Verzweigung anhand der Eingangsprüfung:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei fehlerhafter Null-Referenz führt die linke Kante direkt zum Endknoten für <code>INPUTERR_NULL</code>.</li>\n<li>Bei ungültigen Eingabewerten (<code>[wrong input]</code>) führt die rechte Kante direkt zum Endknoten für Eingabefehler (<code>return E2E_...</code>).</li>\n<li>Bei erfolgreicher Validierung (<code>[input ok]</code>) wird der Hauptpfad sequenziell abgearbeitet:</li>\n</ul>\n<p class=\"fig-p\">a. <code>Compute offset</code></p>\n<p class=\"fig-p\">b. <code>Write Length</code></p>\n<p class=\"fig-p\">c. <code>Write Counter</code></p>\n<p class=\"fig-p\">d. <code>Write DataID</code></p>\n<p class=\"fig-p\">e. <code>Compute CRC</code></p>\n<p class=\"fig-p\">f. <code>Write CRC</code></p>\n<p class=\"fig-p\">g. <code>Increment Counter</code></p>\n<ol class=\"fig-list\">\n<li>Nach dem Inkrementieren des Zählers terminiert die Funktion erfolgreich am mittleren Endknoten mit <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm ist normativ gemäß [PRS_E2E_00362] für das Verhalten der Funktion <code>E2E_P04Protect</code>. Alle Teilaktivitäten sind als aufrufende Aktionen mit referenzierten Sub-Aktivitätsdiagrammen spezifiziert (z. B. <code>Verify inputs of the protect function</code> gemäß [PRS_E2E_00363]). Bei fehlerhaften Parametern bricht der Schutz unverzüglich ohne Modifikation der Nutzdaten oder Zählerinkrementierung ab. Die Absicherungsschritte erfordern deterministische Reihenfolge: Zuerst Platzierung bzw. Berechnung von Offset, Länge, Counter und DataID, danach Berechnung und Eintrag der CRC-Prüfsumme, gefolgt von der Erhöhung des Counters im Zustandsvektor.</p>"}, {"id": "FIG-d7e621bde3752da2", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses der Schutzfunktion <code>E2E_P04Protect</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 4). Das Diagramm spezifiziert die Gesamtabfolge der Schutzschritte bei der Absicherung eines zu übertragenden Datenbereichs auf Senderseite.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitätsaufruf / Funktion</strong>: <code>E2E_P04Protect(Config, State, Data, Length)</code></li>\n<li><strong>Eingangsparameter</strong>:</li>\n<li><code>Config</code>: Konfigurationsstruktur des Profils 4</li>\n<li><code>State</code>: Zustandsstruktur des Schutzes</li>\n<li><code>Data</code>: Zeiger auf das zu schützende Daten-Array</li>\n<li><code>Length</code>: Länge der Daten in Bytes</li>\n<li><strong>Aktionen / Sub-Aktivitäten</strong> (jeweils mit Unterdiagramm-Symbol gekennzeichnet):</li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Write Length</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Write DataID</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n<li><strong>Knoten</strong>: Ein Startknoten (Initial Node) und drei Endknoten (Activity Final Nodes) am unteren Rand (Beschriftungen am Bildrand beschnitten).</li>\n<li><strong>Guards</strong>: <code>[input ok]</code>, <code>[wrong input]</code>, <code>[null input]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf beginnt am Startknoten beim Aufruf von <code>E2E_P04Protect(Config, State, Data, Length)</code>.</li>\n<li>Erste Aktion ist <code>Verify inputs of the protect function</code>.</li>\n<li>Verzweigung anhand der Eingangsprüfung:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei fehlerhafter Null-Referenz führt die linke Kante direkt zum Endknoten für <code>INPUTERR_NULL</code>.</li>\n<li>Bei ungültigen Eingabewerten (<code>[wrong input]</code>) führt die rechte Kante direkt zum Endknoten für Eingabefehler (<code>return E2E_...</code>).</li>\n<li>Bei erfolgreicher Validierung (<code>[input ok]</code>) wird der Hauptpfad sequenziell abgearbeitet:</li>\n</ul>\n<p class=\"fig-p\">a. <code>Compute offset</code></p>\n<p class=\"fig-p\">b. <code>Write Length</code></p>\n<p class=\"fig-p\">c. <code>Write Counter</code></p>\n<p class=\"fig-p\">d. <code>Write DataID</code></p>\n<p class=\"fig-p\">e. <code>Compute CRC</code></p>\n<p class=\"fig-p\">f. <code>Write CRC</code></p>\n<p class=\"fig-p\">g. <code>Increment Counter</code></p>\n<ol class=\"fig-list\">\n<li>Nach dem Inkrementieren des Zählers terminiert die Funktion erfolgreich am mittleren Endknoten mit <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm ist normativ gemäß [PRS_E2E_00362] für das Verhalten der Funktion <code>E2E_P04Protect</code>. Alle Teilaktivitäten sind als aufrufende Aktionen mit referenzierten Sub-Aktivitätsdiagrammen spezifiziert (z. B. <code>Verify inputs of the protect function</code> gemäß [PRS_E2E_00363]). Bei fehlerhaften Parametern bricht der Schutz unverzüglich ohne Modifikation der Nutzdaten oder Zählerinkrementierung ab. Die Absicherungsschritte erfordern deterministische Reihenfolge: Zuerst Platzierung bzw. Berechnung von Offset, Länge, Counter und DataID, danach Berechnung und Eintrag der CRC-Prüfsumme, gefolgt von der Erhöhung des Counters im Zustandsvektor.</p>"}], "trans": [{"from": "FIG-7079db790b9b056c", "to": "FIG-d7e621bde3752da2", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Verzweigungs-Guard am linken Pfad von <code>Verify inputs of the protect function</code>: Guard-Beschriftung <code>[null input]</code> ist nun direkt an der Kante unterhalb der Verzweigung platziert.</li>\n<li>Guard-Beschriftung <code>[wrong input]</code> am rechten Pfad: Zeilenumbruch zu zweizeiliger Darstellung (<code>[wrong</code> / <code>input]</code>).</li>\n<li>Guard-Beschriftung <code>[input ok]</code> am zentralen Pfad: Zeilenumbruch zu zweizeiliger Darstellung (<code>[input</code> / <code>ok]</code>).</li>\n<li>Funktionsaufruf am Startknoten: Signatur <code>E2E_P04Protect(Config, State, Data, Length)</code> zweizeilig umgebrochen (<code>E2E_P04Protect(Config, State, Data,</code> / <code>Length)</code>).</li>\n<li>Endknoten-Beschriftungen am unteren Bildrand: Beschriftungen <code>INPUTERR_NULL</code>, <code>return E2E_E_OK</code> und <code>return E2E_...</code> sind durch verändertes Rendering/Clipping am unteren Rand teilweise abgeschnitten (nur noch Fragmente bzw. <code>return</code> sichtbar).</li>\n</ul>"}]};
